import itertools

def solve_small(n):
    from itertools import permutations

    matches = []
    for i in range(n):
        for j in range(i + 1, n):
            matches.append((i, j))

    m = len(matches)
    min_cost = float('inf')

    for p_matches in permutations(matches):
        f = [float('inf')] * n
        l = [float('-inf')] * n
        for day, (u, v) in enumerate(p_matches, 1):
            f[u] = min(f[u], day)
            l[u] = max(l[u], day)
            f[v] = min(f[v], day)
            l[v] = max(l[v], day)

        cost = 0
        for i in range(n):
            cost += (l[i] - f[i] + 1)

        if cost < min_cost:
            min_cost = cost

    return min_cost

for n in range(2, 6):
    print(f"n={n}, min_cost={solve_small(n)}")

