        f[u] = min(f[u], day)
        l[u] = max(l[u], day)
        f[v] = min(f[v], day)
        l[v] = max(l[v], day)
    return sum(f), sum(l)

def solve_n(n):
    matches = []
    for i in range(n):
        for j in range(i + 1, n):
            matches.append((i, j))
    m = len(matches)

    min_diff = float('inf')
    best_f, best_l = 0, 0

    import random
    for _ in range(10000):
        random.shuffle(matches)
        f_sum, l_sum = get_f_l(n, matches)
        diff = l_sum - f_sum
        if diff < min_diff:
            min_diff = diff
            best_f, best_l = f_sum, l_sum

    return min_diff, best_f, best_l

