import math

def get_cost(n, matches_order):
    f = [10**9] * n
    l = [-10**9] * n
    for day, (u, v) in enumerate(matches_order, 1):
        if day < f[u]: f[u] = day
        if day < f[v]: f[v] = day
        if day > l[u]: l[u] = day
        if day > l[v]: l[v] = day

    cost = 0
    for i in range(n):
        cost += (l[i] - f[i] + 1)
    return cost

def solve_n_simulated_annealing(n, iterations=50000):
    matches = []
    for i in range(n):
        for j in range(i + 1, n):
            matches.append((i, j))

    if len(matches) < 2:
        return get_cost(n, matches)

    current_matches = list(matches)
    random.shuffle(current_matches)
    current_cost = get_cost(n, current_matches)

    min_cost = current_cost

    T = 100.0
    alpha = 0.9999

    for _ in range(iterations):
        idx1, idx2 = random.sample(range(len(current_matches)), 2)
        current_matches[idx1], current_matches[idx2] = current_matches[idx2], current_matches[idx1]
        new_cost = get_cost(n, current_matches)

        if new_cost < current_cost or (T > 0 and random.random() < math.exp((current_cost - new_cost) / T)):
            current_cost = new_cost
            if current_cost < min_cost:
                min_cost = current_cost
        else:
            current_matches[idx1], current_matches[idx2] = current_matches[idx2], current_matches[idx1]

        T *= alpha

    return min_cost

for n in range(2, 9):
    print(f"n={n}, min_cost={solve_n_simulated_annealing(n, 100000)}")

